import { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import SearchForm from './SearchForm';
import RouteList from './RouteList';
import { useNavigate } from 'react-router-dom';
import heroBg from '../hero-bg.jpg';
import '../styles/home.css';

const Home = () => {
  const [routes, setRoutes] = useState([]);
  const [filteredRoutes, setFilteredRoutes] = useState([]);
  const [searchParams, setSearchParams] = useState({ from: '', to: '', date: '' });
  const [isLoading, setIsLoading] = useState(true);
  const [isInitialSearch, setIsInitialSearch] = useState(true);
  const navigate = useNavigate();
  const mainFormRef = useRef(null);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'instant' });
    
    const checkEmailConfirmation = () => {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('emailConfirmed')) {
        navigate('/', { replace: true });
        setTimeout(() => alert('✅ Email подтверждён!'), 300);
      }
    };

    const fetchRoutes = async () => {
      try {
        const { data } = await axios.get('/api/routes');
        setRoutes(data);
        setFilteredRoutes(data);
        setIsLoading(false);
      } catch (err) {
        console.error('Ошибка загрузки маршрутов:', err);
        setIsLoading(false);
      }
    };

    checkEmailConfirmation();
    fetchRoutes();
  }, [navigate]);

  const handleSearch = useCallback((params) => {
    const filtered = routes.filter(route => {
      const matchFrom = params.from ? route.from.toLowerCase().includes(params.from.toLowerCase()) : true;
      const matchTo = params.to ? route.to.toLowerCase().includes(params.to.toLowerCase()) : true;
      const routeDate = new Date(route.date);
      const searchDate = params.date ? new Date(params.date) : null;
      
      return matchFrom && matchTo && (!searchDate || 
        routeDate.getFullYear() === searchDate.getFullYear() &&
        routeDate.getMonth() === searchDate.getMonth() &&
        routeDate.getDate() === searchDate.getDate());
    });

    setFilteredRoutes(filtered);
    setSearchParams(params);

    if (isInitialSearch) {
      setIsInitialSearch(false);
      setTimeout(() => {
        mainFormRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    }
  }, [routes, isInitialSearch]);

  const handleReset = useCallback(() => {
    setIsInitialSearch(true);
    setSearchParams({ from: '', to: '', date: '' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <div className="home-page">
      <section className={`hero-section ${!isInitialSearch ? 'hidden' : ''}`}>
        <div className="hero-overlay" />
        <div className="hero-content">
          <h1 className="hero-title">Найдите идеальное путешествие</h1>
          <p className="hero-subtitle">Откройте лучшие направления по выгодным ценам</p>
          <SearchForm 
            onSearch={handleSearch}
            initialValues={searchParams}
            wide={true}
            isLoading={isLoading}
          />
        </div>
      </section>

      <section className={`features-wrapper ${!isInitialSearch ? 'hidden' : ''}`}>
        <div className="features-container">
          <h2 className="features-title">Почему выбирают нас</h2>
          <div className="features-grid">
            <div className="feature-item">
              <div className="feature-icon">⚡</div>
              <div className="feature-content">
                <h3>Быстро и удобно</h3>
                <p>Ищите и бронируйте билеты за пару кликов</p>
              </div>
            </div>
            <div className="feature-item">
              <div className="feature-icon">🛡️</div>
              <div className="feature-content">
                <h3>Надёжность</h3>
                <p>Работаем только с проверенными перевозчиками</p>
              </div>
            </div>
            <div className="feature-item">
              <div className="feature-icon">💰</div>
              <div className="feature-content">
                <h3>Экономия</h3>
                <p>Лучшие цены без скрытых платежей</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className={`main-layout ${isInitialSearch ? 'hidden' : ''}`} ref={mainFormRef}>
        <div className="content-wrapper">
          <main className="main-content">
            <SearchForm 
              onSearch={handleSearch}
              initialValues={searchParams}
              wide={false}
              isLoading={isLoading}
            />
            <div className="routes-wrapper">
              {filteredRoutes.length > 0 ? (
                <RouteList routes={filteredRoutes} />
              ) : (
                <div className="no-routes">🗺️ Маршруты не найдены</div>
              )}
            </div>
          </main>
          
          <aside className="sidebar">
            <div className="sidebar-card help-card">
              <h4>🚀 Помощь в поездке</h4>
              <ul className="help-list">
                <li>📞 8-800-123-45-67</li>
                <li>📄 Условия возврата</li>
                <li>📍 Пункты отправления</li>
                <li>💳 Онлайн оплата</li>
              </ul>
            </div>
          </aside>
        </div>
      </section>
    </div>
  );
};

export default Home;
